# Python 3.13+ demonstration of Crisp vs Fuzzy evaluation

def crisp_tall(height):
    # Sharp cutoff at 180 cm
    return 1 if height >= 180 else 0

def fuzzy_tall(height):
    # Gradual membership function between 150cm and 190cm
    if height <= 150:
        return 0.0
    elif height >= 190:
        return 1.0
    else:
        return (height - 150) / (190 - 150)

print("Crisp (175cm):", crisp_tall(175))
print("Fuzzy (175cm):", fuzzy_tall(175))

