# Python 3.13+ representation of a fuzzy set using dictionary/mapping

class FuzzySet:
    def __init__(self, name, universe_dict):
        # universe_dict maps element -> membership degree [0, 1]
        self.name = name
        self.elements = universe_dict

    def support(self):
        return [k for k, v in self.elements.items() if v > 0]

    def core(self):
        return [k for k, v in self.elements.items() if v == 1]

