def uniform_crossover(p1, p2, prob=0.5):
    c1, c2 = [], []
    for gene1, gene2 in zip(p1, p2):
        if random.random() < prob:
            c1.append(gene2); c2.append(gene1)
        else:
            c1.append(gene1); c2.append(gene2)
    return c1, c2

