import random

def bit_flip_mutation(chromosome, pm=0.1):
    mutated = []
    for gene in chromosome:
        if random.random() < pm:
            # Flip bit: 0 -> 1 or 1 -> 0
            mutated.append(1 - gene)
        else:
            mutated.append(gene)
    return mutated

chrom = [1, 0, 1, 1, 0]
print('Mutated:', bit_flip_mutation(chrom, pm=0.4))

